export type EgyptGeoShiyakha = {
  id: string;
  name: string;
  nameEn: string;
  districtId: string;
  lat: number;
  lon: number;
};

export type EgyptAdministrativeMatch = {
  governorate: EgyptGeoGovernorate;
  district: EgyptGeoDistrict | null;
  shiyakha: EgyptGeoShiyakha | null;
  level: 'SHIYAKHA' | 'DISTRICT' | 'GOVERNORATE';
  distanceKm: number;
};

const shiyakhaCache = new Map<string, Promise<EgyptGeoShiyakha[]>>();

const validPoint = (lat: number, lon: number) =>
  Number.isFinite(lat) && Number.isFinite(lon) && Math.abs(lat) <= 90 && Math.abs(lon) <= 180;

export const egyptDistanceKm = (lat1: number, lon1: number, lat2: number, lon2: number): number => {
  const rad = (value: number) => value * Math.PI / 180;
  const dLat = rad(lat2 - lat1);
  const dLon = rad(lon2 - lon1);
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(rad(lat1)) * Math.cos(rad(lat2)) * Math.sin(dLon / 2) ** 2;
  return 6371 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(Math.max(0, 1 - a)));
};

/**
 * Loads locality names and representative points for one district only.
 * The request sends the public district slug, never the visitor's GPS coordinates.
 */
export const loadEgyptDistrictShiyakhas = (district: EgyptGeoDistrict): Promise<EgyptGeoShiyakha[]> => {
  const cached = shiyakhaCache.get(district.id);
  if (cached) return cached;

  const request = fetch(`https://openadmindata.org/api/v1/eg/district/${encodeURIComponent(district.slug)}.json`, {
    headers: { Accept: 'application/json' },
    credentials: 'omit',
    referrerPolicy: 'no-referrer',
  }).then(async (response) => {
    if (!response.ok) throw new Error(`Administrative data request failed: ${response.status}`);
    const payload: unknown = await response.json();
    if (!Array.isArray(payload)) throw new Error('Administrative data payload is not an array');
    return payload.flatMap((value: any) => {
      if (!value || typeof value !== 'object' || value.level !== 3 ||
          value.parent?.id !== district.id || typeof value.id !== 'string' ||
          typeof value.name?.local !== 'string') return [];
      const lat = Number(value.geo?.lat);
      const lon = Number(value.geo?.lon);
      if (!validPoint(lat, lon)) return [];
      return [{
        id: value.id,
        name: value.name.local,
        nameEn: typeof value.name.en === 'string' ? value.name.en : '',
        districtId: district.id,
        lat,
        lon,
      } satisfies EgyptGeoShiyakha];
    });
  }).catch((error) => {
    shiyakhaCache.delete(district.id);
    throw error;
  });

  shiyakhaCache.set(district.id, request);
  return request;
};

/**
 * Nearest-point administrative suggestion, not point-in-polygon proof.
 * It compares the five nearest district representative points, then accepts
 * a shiyakha match only when its representative point is within 8 km.
 */
export const resolveEgyptAdministrativeLocation = async (
  latitude: number,
  longitude: number,
): Promise<EgyptAdministrativeMatch | null> => {
  if (!validPoint(latitude, longitude) || latitude < 21.5 || latitude > 32.2 || longitude < 24 || longitude > 37.5) return null;

  const nearestDistricts = EGYPT_GEO_DISTRICTS
    .map((district) => ({
      district,
      distanceKm: egyptDistanceKm(latitude, longitude, district.lat, district.lon),
    }))
    .sort((a, b) => a.distanceKm - b.distanceKm)
    .slice(0, 5);

  const nearestDistrict = nearestDistricts[0];
  if (!nearestDistrict || nearestDistrict.distanceKm > 35) {
    const nearestGovernorate = EGYPT_GEO_GOVERNORATES
      .map((governorate) => ({
        governorate,
        distanceKm: egyptDistanceKm(latitude, longitude, governorate.lat, governorate.lon),
      }))
      .sort((a, b) => a.distanceKm - b.distanceKm)[0];
    if (!nearestGovernorate || nearestGovernorate.distanceKm > 100) return null;
    return {
      governorate: nearestGovernorate.governorate,
      district: null,
      shiyakha: null,
      level: 'GOVERNORATE',
      distanceKm: nearestGovernorate.distanceKm,
    };
  }

  const candidates = await Promise.allSettled(
    nearestDistricts.filter((item) => item.distanceKm <= 35).map((item) => loadEgyptDistrictShiyakhas(item.district)),
  );

  const shiyakhaCandidates = candidates.flatMap((result) =>
    result.status === 'fulfilled' ? result.value : [],
  ).map((shiyakha) => ({
    shiyakha,
    distanceKm: egyptDistanceKm(latitude, longitude, shiyakha.lat, shiyakha.lon),
  })).sort((a, b) => a.distanceKm - b.distanceKm);

  const nearestShiyakha = shiyakhaCandidates[0];
  if (nearestShiyakha && nearestShiyakha.distanceKm <= 8) {
    const district = EGYPT_GEO_DISTRICTS.find((item) => item.id === nearestShiyakha.shiyakha.districtId);
    const governorate = district && EGYPT_GEO_GOVERNORATES.find((item) => item.id === district.governorateId);
    if (district && governorate) {
      return {
        governorate,
        district,
        shiyakha: nearestShiyakha.shiyakha,
        level: 'SHIYAKHA',
        distanceKm: nearestShiyakha.distanceKm,
      };
    }
  }

  const governorate = EGYPT_GEO_GOVERNORATES.find((item) => item.id === nearestDistrict.district.governorateId);
  if (!governorate) return null;
  return {
    governorate,
    district: nearestDistrict.district,
    shiyakha: null,
    level: 'DISTRICT',
    distanceKm: nearestDistrict.distanceKm,
  };
};
